cat > /tmp/add_precision_var.txt << 'EOF'
	// DurationFieldInteger renders Dur fields as integer instead of float if
	// set to true.
	DurationFieldInteger = false

	// FloatingPointPrecision sets the precision for floating point numbers.
	// If set to -1 (default), the precision is determined automatically.
	// If set to a non-negative value, it specifies the number of digits after
	// the decimal point.
	FloatingPointPrecision = -1

	// ErrorHandler is called whenever zerolog fails to write an event on its
	// output. If not set, an error is printed on the stderr. This handler must
	// be thread safe and non-blocking.
	ErrorHandler func(err error)
EOF
sed -n '107,118p' /testbed/globals.go

sed -i '116a\n	// FloatingPointPrecision sets the precision for floating point numbers.
	// If set to -1 (default), the precision is determined automatically.
	// If set to a non-negative value, it specifies the number of digits after
	// the decimal point.
	FloatingPointPrecision = -1' /testbed/globals.go
